local MonsterList = {}
local nums = 0;

---@private
function MonsterMgr:init()
    local cfgs = MonsterGenerateConfig:getAllCfgs()
    for id, cfg in pairs(cfgs) do
        if cfg.spawnTime > 0 then
            GidRecord[id] = os.time() + cfg.spawnTime
        end
    end
    self.lastCheckPosTime = 0
    LuaTimer:scheduleTimer(function()
        self:onTick()
    end, 1000)
end

---@private
function MonsterMgr:onTick()
    local time = os.time()
    
    local cfgs = MonsterGenerateConfig:getAllCfgs()
    local weekDay = DateUtil.getWeekDay() - 1
    if weekDay == 0 then
        weekDay = 7
    end
    for id, cfg in pairs(cfgs) do
        -- LogUtil.logInfo("[MonsterMgr] check gid: " .. id .. " time: " .. time .. " record: ")
        local record = GidRecord[id] or 0
        -- if not TableUtil.tableContain(cfg.weekDay, weekDay) then
        --     GidRecord[id] = time + 5
        --     goto CONTINUE
        -- end
        -- if time < record then
        --     self:tryAddCountdown(cfg, record)
        --     goto CONTINUE
        -- endp
        if nums >= 2 then 
            goto CONTINUE
        end
        GidRecord[id] = nil
        nums = nums + 1
        self:createMonster(id, cfg.monsterId, cfg.position)
        :: CONTINUE ::
    end
    if GameType ~= "g1050" then
        return
    end
    if os.time() - self.lastCheckPosTime > 180 then
        self.lastCheckPosTime = os.time()
        self:resetFallingMonsterPos()
    end
end

---@private
---@param cfg MonsterGenerateConfigData
function MonsterMgr:tryAddCountdown(cfg, refreshTime)
    if not cfg.refreshTip then
        return
    end
    if CountdownActor[cfg.id] then
        return
    end
    local entityId = EngineWorld:addActorNpc(cfg.position, 0, "g1048_item_hallow_tombstone01.actor", function(entity)
        local builder = DataBuilder.new():fromTable({
            interface = "MonsterCountdown",
            monsterId = cfg.monsterId,
            refreshTime = refreshTime,
        })
        entity:setCustomProperties(builder:getData())
    end)
    CountdownActor[cfg.id] = entityId
end

---@private
function MonsterMgr:removeCountdown(gid)
    local entityId = CountdownActor[gid] or 0
    if entityId ~= 0 then
        EngineWorld:removeEntity(entityId)
    end
end

---@private
function MonsterMgr:createMonster(gid, monsterId, position)
    LogUtil.logInfo("[MonsterMgr] createMonster gid: " .. gid .. " monsterId: " .. monsterId .. " position:" )
    if GidRecord[gid] then
        return
    end
    if not self:createMonsterEntity(gid, monsterId, position) then
        return
    end
    GidRecord[gid] = os.time() + 864000000
    self:removeCountdown(gid)
    CountdownActor[gid] = 0
end

function MonsterMgr:getMonsterList()
    return MonsterList
end

---@return SEntityMonster
function MonsterMgr:getMonsterById(entityId)
    return MonsterList[entityId]
end

function MonsterMgr:createMonsterEntity(gid, monsterId, position)
    local cfg = MonsterConfig:getCfgById(monsterId)
    if not cfg then
        LogUtil.logError("[MonsterMgr] createMonsterEntity monsterId: " .. monsterId .. " not exist")
        return nil
    end
    local entityId = EngineWorld:addCreatureNpc(position, monsterId, 0, cfg.actorName, function(entity)
        if cfg.name == "#" then
            entity:setNameLang("")
        else
            entity:setNameLang(cfg.name)
        end
        entity:setCustomProperties(gid .. ":" .. monsterId)
    end)
    EngineWorld:getWorld():setCreatureHome(entityId, VectorUtil.toVector3i(position))
    EngineWorld:getWorld():setEntityHealth(entityId, cfg.hp, cfg.hp)
    ---@type SEntityMonster
    local entity = EntityCache:getEntity(entityId)
    entity.gid = gid
    entity:setConfig(cfg)
    MonsterList[entityId] = entity
    return entity
end

function MonsterMgr:removeMonsterEntity(entityId)
    MonsterList[entityId] = nil
end

---@param monster SEntityMonster
function MonsterMgr:onMonsterDead(monster)
    local cfg = MonsterGenerateConfig:getCfgById(monster.gid)
    if cfg then
        GidRecord[monster.gid] = os.time() + cfg.refreshCD
    end
    CountdownActor[monster.gid] = nil
end

function MonsterMgr:resetAllMonster()
    for gid, entityId in pairs(CountdownActor) do
        EngineWorld:removeEntity(entityId)
        CountdownActor[gid] = 0
    end
    local time = os.time() + 864000
    for gid, record in pairs(GidRecord) do
        if time > record then
            GidRecord[gid] = 0
        end
    end
    local weekDay = DateUtil.getWeekDay() - 1
    if weekDay == 0 then
        weekDay = 7
    end
    ---@param entity SEntityMonster
    for _, entity in pairs(MonsterList) do
        if entity.battle then
            goto CONTINUE
        end
        local cfg = MonsterGenerateConfig:getCfgById(entity.gid)
        if not cfg or cfg.spawnTime > 0 then
            entity.isDead = true
            if cfg then
                CountdownActor[cfg.id] = nil
            end
            if entity.cfg.isBoss then
                ReportEvent.reportEvent("game", "on_boss_recycle", false, {
                    owner_id = entity.cfg.id,
                })
            end
            EngineWorld:removeEntity(entity.entityId)
        elseif TableUtil.tableContain(cfg.weekDay, weekDay) then
            entity:doReset()
        end
        :: CONTINUE ::
    end
    local cfgs = MonsterGenerateConfig:getAllCfgs()
    for id, cfg in pairs(cfgs) do
        if cfg.spawnTime > 0 then
            GidRecord[id] = os.time() + cfg.spawnTime
        end
    end
end

function MonsterMgr:resetAllMonsterPos()
    ---@param entity SEntityMonster
    for _, entity in pairs(MonsterList) do
        local cfg = MonsterGenerateConfig:getCfgById(entity.gid)
        if cfg and cfg.resetPos then
            entity.entity:setPosition(cfg.position)
        end
    end
end

function MonsterMgr:spawnAllMonster()
    for gid, entityId in pairs(CountdownActor) do
        EngineWorld:removeEntity(entityId)
        CountdownActor[gid] = 0
    end
    local time = os.time() + 864000
    for gid, record in pairs(GidRecord) do
        if time > record then
            GidRecord[gid] = 0
        end
    end
end

function MonsterMgr:resetFallingMonsterPos()
    ---@param entity SEntityMonster
    for _, entity in pairs(MonsterList) do
        local cfg = MonsterGenerateConfig:getCfgById(entity.gid)
        if cfg then
            if entity.entity:getPosition().y < cfg.position.y - 30 then
                entity.entity:setPosition(cfg.position)
            end
        end
    end
end

MonsterMgr:init()

return MonsterMgr